def construir_arbol(rutas):
    arbol = {}
    for ruta in rutas:
        partes = ruta.split('/')
        nodo_actual = arbol
        for parte in partes:
            if parte not in nodo_actual:
                nodo_actual[parte] = {}
            nodo_actual = nodo_actual[parte]
    return arbol
